package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.special.Beta;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link FDistribution#getNumericalMean()}.
 */
public class FDistribution_getNumericalMean_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetNumericalMean_DenominatorGreaterThanTwo() {
        // Case where denominatorDF > 2
        // Expected: denominatorDF / (denominatorDF - 2)
        // If denominatorDF = 4.0, mean = 4.0 / (4.0 - 2.0) = 2.0
        double numeratorDF = 5.0;
        double denominatorDF = 4.0;
        FDistribution distribution = new FDistribution(numeratorDF, denominatorDF);

        double expected = 2.0;
        double actual = distribution.getNumericalMean();

        assertEquals("Mean should be denominatorDF / (denominatorDF - 2) when denominatorDF > 2", 
                     expected, actual, EPSILON);
    }

    @Test
    public void testGetNumericalMean_DenominatorEqualToTwo() {
        // Case where denominatorDF == 2
        // The condition is (denominatorDF > 2), so this should return Double.NaN
        double numeratorDF = 5.0;
        double denominatorDF = 2.0;
        FDistribution distribution = new FDistribution(numeratorDF, denominatorDF);

        double actual = distribution.getNumericalMean();

        assertTrue("Mean should be NaN when denominatorDF is exactly 2", 
                   Double.isNaN(actual));
    }

    @Test
    public void testGetNumericalMean_DenominatorLessThanTwo() {
        // Case where denominatorDF < 2
        // The condition is (denominatorDF > 2), so this should return Double.NaN
        double numeratorDF = 5.0;
        double denominatorDF = 1.5;
        FDistribution distribution = new FDistribution(numeratorDF, denominatorDF);

        double actual = distribution.getNumericalMean();

        assertTrue("Mean should be NaN when denominatorDF is less than 2", 
                   Double.isNaN(actual));
    }

    @Test(expected = NotStrictlyPositiveException.class)
    public void testConstructor_InvalidParameters() {
        // Testing constructor edge case to ensure we can instantiate valid objects for the method test
        new FDistribution(-1.0, 4.0);
    }

    @Test
    public void testGetNumericalMean_LargeDenominator() {
        // Testing with a large value to ensure precision
        double numeratorDF = 10.0;
        double denominatorDF = 102.0;
        FDistribution distribution = new FDistribution(numeratorDF, denominatorDF);

        // 102 / (102 - 2) = 102 / 100 = 1.02
        double expected = 1.02;
        double actual = distribution.getNumericalMean();

        assertEquals("Mean calculation failed for large denominator", expected, actual, EPSILON);
    }
}
